import type { LocationType } from "@/lib/domain/types";

/**
 * Bangladesh location reference data.
 *
 * This file is the single source for:
 *   - supabase/migrations/20261008000600_reference_data.sql (generated by
 *     `npm run db:generate`), which loads it into the `locations` table, and
 *   - demo mode, when no database is connected.
 *
 * Components never import it. They ask the data layer (src/lib/data), which
 * reads the database when one is configured.
 *
 * Coverage in Phase 1: all 8 divisions, all 64 districts, the main cities, and
 * the neighbourhoods where most property is listed. Coordinates are rough
 * centre points for map placement, not surveyed boundaries. The full upazila
 * and thana list can be bulk-loaded through the CSV import planned for Phase 4.
 *
 * Slug rules: divisions end in "-division", districts in "-district"; cities,
 * upazilas and areas use the plain name, so "/rent/dhaka" means the city.
 */

export interface LocationSeed {
  slug: string;
  type: LocationType;
  parent: string | null;
  nameBn: string;
  nameEn: string;
  /** Other spellings people type, in Bangla or English. Used by search. */
  altNames: string[];
  latitude: number;
  longitude: number;
  isPopular: boolean;
  sortOrder: number;
}

type Row = [slug: string, nameBn: string, nameEn: string, lat: number, lng: number, altNames?: string[]];

